_POR_CFG.setdefault(((128, 128, 128, 8, 8, 3), False), []).append(_VAR_4)
_POR_CFG.setdefault(((128, 128, 128, 8, 8, 3), False), []).append(_VAR_5)
_POR_CFG.setdefault(((128, 128, 128, 8, 8, 3), True), []).append(_VAR_6)
